def cc_count(a,conn8=False):
 a=np.array(a)!=0; seen=set(); comps=[]
 for i in range(4):
  for j in range(4):
   if a[i,j] and (i,j) not in seen:
    stack=[(i,j)];seen.add((i,j)); comp=[]
    while stack:
     x,y=stack.pop();comp.append((x,y))
     for dx in (-1,0,1):
      for dy in (-1,0,1):
       if dx==dy==0 or (not conn8 and abs(dx)+abs(dy)!=1):continue
       xx,yy=x+dx,y+dy
       if 0<=xx<4 and 0<=yy<4 and a[xx,yy] and (xx,yy) not in seen: seen.add((xx,yy));stack.append((xx,yy))
    comps.append(len(comp))
 return sorted(comps,reverse=True)
for di,g in enumerate(inputs):
 print('demo',di+1,[(colors[di][k],cc_count(arr(g,r,c)),cc_count(arr(g,r,c),True)) for k,(r,c) in enumerate(reg)])
